begin;
select plan(21);
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-0000000000a1',true);
select lives_ok($$select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000001','add','{"id": "10000000-0000-4000-8000-000000000101", "name": "arroz", "raw_text": "arroz", "quantity": 500, "unit": "g"}'::jsonb)$$,'add reviewed ingredient');
select lives_ok($$select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000001','add','{"id": "10000000-0000-4000-8000-000000000101", "name": "arroz", "raw_text": "arroz", "quantity": 500, "unit": "g"}'::jsonb)$$,'retry same operation');
select is((select count(*)::int from public.shopping_items),1,'no duplicate retry');
select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000002','add','{"id": "10000000-0000-4000-8000-000000000102", "name": "arroz", "raw_text": "arroz", "quantity": 0.5, "unit": "kg"}'::jsonb);
select is((select quantity from public.shopping_items where name='arroz'),1000::numeric,'kg g merged');
select is((select jsonb_array_length(sources) from public.shopping_items where name='arroz'),2,'raw contributions retained');
select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000003','add','{"id": "10000000-0000-4000-8000-000000000103", "name": "arroz", "raw_text": "arroz", "quantity": 20, "unit": "ml"}'::jsonb);
select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000004','add','{"id": "10000000-0000-4000-8000-000000000104", "name": "arroz", "raw_text": "arroz", "quantity": 1, "unit": "lata"}'::jsonb);
select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000005','add','{"id": "10000000-0000-4000-8000-000000000105", "name": "tomate entero", "raw_text": "tomate entero", "quantity": 20, "unit": "g"}'::jsonb);
select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000006','add','{"id": "10000000-0000-4000-8000-000000000106", "name": "tomate triturado", "raw_text": "tomate triturado", "quantity": 20, "unit": "g"}'::jsonb);
select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000007','add','{"id": "10000000-0000-4000-8000-000000000107", "name": "pollo", "raw_text": "pollo", "quantity": 20, "unit": "g", "preparation": "crudo"}'::jsonb);
select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000008','add','{"id": "10000000-0000-4000-8000-000000000108", "name": "pollo", "raw_text": "pollo", "quantity": 20, "unit": "g", "preparation": "cocinado"}'::jsonb);
select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000009','add','{"id": "10000000-0000-4000-8000-000000000109", "name": "sal", "raw_text": "sal", "quantity": null, "unit": null}'::jsonb);
select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000010','add','{"id": "10000000-0000-4000-8000-000000000110", "name": "papel de cocina", "raw_text": "papel de cocina", "quantity": null, "unit": null}'::jsonb);
select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000011','add','{"id": "10000000-0000-4000-8000-000000000111", "name": "arroz", "raw_text": "arroz", "quantity": 2, "unit": "g", "quantity_max": 3}'::jsonb);
select is((select count(*)::int from public.shopping_items),10,'incompatible units forms states and ranges separate');
select throws_ok($$select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000020','edit','{"id": "10000000-0000-4000-8000-000000000101", "revision": 1, "name": "otro"}'::jsonb)$$,'40001','shopping_revision_conflict','stale quantity edit retained as conflict');
select lives_ok($$select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000021','checked','{"id": "10000000-0000-4000-8000-000000000101", "revision": 1, "checked": true}'::jsonb)$$,'absolute checked accepts stale revision');
select lives_ok($$select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000022','delete','{"id": "10000000-0000-4000-8000-000000000101", "revision": 3}'::jsonb)$$,'tombstone');
select throws_ok($$select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000023','checked','{"id": "10000000-0000-4000-8000-000000000101", "checked": false}'::jsonb)$$,'P0002','item_deleted_or_missing','checked cannot resurrect');
select lives_ok($$select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000001','add','{"id": "10000000-0000-4000-8000-000000000101", "name": "arroz", "raw_text": "arroz", "quantity": 500, "unit": "g"}'::jsonb)$$,'old add receipt after tombstone');
select ok((select deleted_at is not null from public.shopping_items where id='10000000-0000-4000-8000-000000000101'),'replay did not resurrect');
select throws_ok($$update public.shopping_items set revision=99$$,'42501','shopping_rpc_required','direct audit write blocked');
select throws_ok($$select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000001','delete','{"id": "10000000-0000-4000-8000-000000000101", "revision": 4}'::jsonb)$$,'23505','operation_id_reused','key cannot change payload');
select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000090','add','{"id":"10000000-0000-4000-8000-000000000190","name":"tomate entero","raw_text":"500 g tomate entero de lata","quantity":500,"unit":"g"}');
select is((select count(*)::int from public.shopping_items where name='tomate entero'),2,'raw commercial form omitted from name prevents merge');
select lives_ok($$select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000091','add','{"id":"10000000-0000-4000-8000-000000000191","name":"sal","raw_text":"hasta 3 g de sal","quantity":null,"quantity_max":3,"unit":"g"}')$$,'upper bound preserves unknown lower quantity');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-0000000000b2',true);
select is((select count(*)::int from public.shopping_lists),0,'B cannot read A list');
select is((select count(*)::int from public.shopping_items),0,'B cannot read A items');
select throws_ok($$select public.shopping_mutation_v1('10000000-0000-4000-8000-000000000030','edit','{"id": "10000000-0000-4000-8000-000000000105", "revision": 1, "name": "stolen"}'::jsonb)$$,'P0002','item_deleted_or_missing','B cannot modify A');
select is((select count(*)::int from private.shopping_operations),0,'B cannot read receipts');
select is((public.shopping_snapshot_v1()->'items'), '[]'::jsonb,'B snapshot isolated');
reset role;select * from finish();rollback;
